function ResizablePanels() {
  const [splitPct, setSplitPct] = useState(50);
  const [dragging, setDragging]  = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!dragging) return;

    const onMove = (e: MouseEvent) => {
      if (!containerRef.current) return;
      const { left, width } = containerRef.current.getBoundingClientRect();
      const pct = ((e.clientX - left) / width) * 100;
      setSplitPct(Math.max(15, Math.min(85, pct))); // clamp 15–85%
    };

    const onUp = () => setDragging(false);

    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup',   onUp);
    return () => {
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseup',   onUp);
    };
  }, [dragging]);

  return (
    <div ref={containerRef} style={{ display: 'flex', height: '400px' }}>
      <div style={{ width: `${splitPct}%`, overflow: 'auto' }}>Left</div>
      <div
        onMouseDown={() => setDragging(true)}
        style={{ width: 6, background: '#475569', cursor: 'col-resize', flexShrink: 0 }}
      />
      <div style={{ flex: 1, overflow: 'auto' }}>Right</div>
    </div>
  );
}
