function SortableList() {
  const [items, setItems] = useState([
    { id: '1', text: 'Item 1' },
    { id: '2', text: 'Item 2' },
    { id: '3', text: 'Item 3' },
  ]);
  const dragId = useRef<string | null>(null);
  const [overIndex, setOverIndex] = useState<number | null>(null);

  const reorder = (draggedId: string, targetId: string) => {
    setItems(prev => {
      const next = [...prev];
      const from = next.findIndex(i => i.id === draggedId);
      const to   = next.findIndex(i => i.id === targetId);
      next.splice(to, 0, next.splice(from, 1)[0]); // insert, not swap
      return next;
    });
  };

  return (
    <ul style={{ listStyle: 'none', padding: 0 }}>
      {items.map((item, idx) => (
        <li
          key={item.id}
          draggable
          onDragStart={() => { dragId.current = item.id; }}
          onDragOver={e  => { e.preventDefault(); setOverIndex(idx); }}
          onDragLeave={() => setOverIndex(null)}
          onDrop={e     => {
            e.preventDefault();
            if (dragId.current) reorder(dragId.current, item.id);
            setOverIndex(null);
          }}
          style={{
            padding: '12px', margin: '4px', cursor: 'grab',
            background: overIndex === idx ? '#1e293b' : '#0f172a',
            border: `2px solid ${overIndex === idx ? '#22d3ee' : 'transparent'}`,
            borderRadius: 6, color: '#e2e8f0'
          }}
        >
          {item.text}
        </li>
      ))}
    </ul>
  );
}
