// Tooltip that positions itself without flickering
function Tooltip({ anchor, content }: Props) {
  const tooltipRef = useRef<HTMLDivElement>(null);
  const [position, setPosition] = useState<'top' | 'bottom'>('top');

  useLayoutEffect(() => {
    if (!tooltipRef.current || !anchor.current) return;
    const anchorRect  = anchor.current.getBoundingClientRect();
    const tooltipRect = tooltipRef.current.getBoundingClientRect();
    const spaceAbove  = anchorRect.top;
    const spaceBelow  = window.innerHeight - anchorRect.bottom;
    // Decide position synchronously — before paint
    setPosition(tooltipRect.height <= spaceAbove ? 'top' : 'bottom');
  });

  return (
    <div ref={tooltipRef} className={`tooltip tooltip--${position}`}>
      {content}
    </div>
  );
}
