export const useCartStore = create<CartStore>()(
  persist(
    (set, get) => ({
      items: [],
      addItem: item =>
        set(s => ({ items: [...s.items, item] })),
      removeItem: id =>
        set(s => ({ items: s.items.filter(i => i.id !== id) })),
      total: () =>
        get().items.reduce((sum, i) => sum + i.price * i.quantity, 0),
    }),
