  list:   publicProcedure.query(...)    // no auth needed
  create: protectedProcedure            // ctx.user guaranteed
    .input(z.object({ title: z.string() }))
    .mutation(({ ctx, input }) => {
      return db.post.create({ data: { ...input, authorId: ctx.user.id } });
      //                                          ^^^ no null check needed
    }),
  delete: adminProcedure.mutation(...)  // admin only
});
