// Node.js server
import { WebSocketServer } from 'ws';
const wss = new WebSocketServer({ port: 8080 });
const rooms = new Map<string, Set<WebSocket>>();

wss.on('connection', (ws, req) => {
  const room = new URL(req.url!, 'ws://localhost').searchParams.get('room') ?? 'general';
  if (!rooms.has(room)) rooms.set(room, new Set());
  rooms.get(room)!.add(ws);

  ws.on('message', data => {
    // Broadcast to room only
    rooms.get(room)?.forEach(client => {
      if (client !== ws && client.readyState === WebSocket.OPEN) client.send(data);
    });
  });
  ws.on('close', () => rooms.get(room)?.delete(ws));
});

// React hook
function useWebSocket(url: string) {
  const [messages, setMessages] = useState<string[]>([]);
  const [status, setStatus] = useState<'connecting'|'open'|'closed'>('connecting');
  const wsRef = useRef<WebSocket | null>(null);

  useEffect(() => {
    const ws = new WebSocket(url);
    wsRef.current = ws;
    ws.onopen    = () => setStatus('open');
    ws.onclose   = () => setStatus('closed');
    ws.onmessage = e  => setMessages(p => [...p, e.data]);
    return () => { ws.close(); wsRef.current = null; }; // ← critical cleanup
  }, [url]);

  const send = useCallback((msg: string) => {
    if (wsRef.current?.readyState === WebSocket.OPEN) wsRef.current.send(msg);
  }, []);

  return { messages, status, send };
}
