```tsx
// Simplified WebRTC hook
function useWebRTC(roomId: string) {
  const localRef  = useRef<HTMLVideoElement>(null);
  const remoteRef = useRef<HTMLVideoElement>(null);
  const pc   = useRef<RTCPeerConnection | null>(null);
  const ws   = useRef<WebSocket | null>(null);

  useEffect(() => {
    ws.current = new WebSocket(`wss://signal.example.com?room=${roomId}`);

    // 1. Get local camera/mic
    navigator.mediaDevices.getUserMedia({ video: true, audio: true })
      .then(stream => {
        localRef.current!.srcObject = stream;

        pc.current = new RTCPeerConnection({
          iceServers: [{ urls: 'stun:stun.l.google.com:19302' }]
        });

        // 2. Add local tracks to connection
        stream.getTracks().forEach(t => pc.current!.addTrack(t, stream));

        // 3. When remote tracks arrive, show them
        pc.current.ontrack = e => { remoteRef.current!.srcObject = e.streams[0]; };

        // 4. Send ICE candidates to peer via signaling server
        pc.current.onicecandidate = e => {
          if (e.candidate) ws.current!.send(JSON.stringify({ type: 'ice', candidate: e.candidate }));
        };
      });

    // 5. Handle signaling messages
    ws.current.onmessage = async ({ data }) => {
      const msg = JSON.parse(data);
      if (msg.type === 'offer') {
        await pc.current!.setRemoteDescription(msg.sdp);
        const answer = await pc.current!.createAnswer();
        await pc.current!.setLocalDescription(answer);
        ws.current!.send(JSON.stringify({ type: 'answer', sdp: answer }));
      } else if (msg.type === 'answer') {
        await pc.current!.setRemoteDescription(msg.sdp);
      } else if (msg.type === 'ice') {
        await pc.current!.addIceCandidate(msg.candidate);
      }
    };

    return () => { pc.current?.close(); ws.current?.close(); };
  }, [roomId]);

  const call = async () => {
    const offer = await pc.current!.createOffer();
    await pc.current!.setLocalDescription(offer);
    ws.current!.send(JSON.stringify({ type: 'offer', sdp: offer }));
  };

  return { localRef, remoteRef, call };
}
