export default {
  async fetch(req: Request, env: Env) {
    const country  = req.cf?.country as string ?? 'US';
    const currency = { US:'USD', GB:'GBP', EU:'EUR', JP:'JPY' }[country] ?? 'USD';

    // CF Workers bonus: KV store at the edge
    const cached = await env.CACHE.get(`currency:${country}`);
    if (cached) return new Response(cached);

    const result = JSON.stringify({ country, currency });
    await env.CACHE.put(`currency:${country}`, result, { expirationTtl: 3600 });
    return new Response(result, { headers: { 'Content-Type': 'application/json' } });
  }
};
