.hero-image {
  animation: parallax linear;
  animation-timeline: scroll(root);
  animation-range: 0% 50%; /* only first half of scroll */
}
@keyframes parallax {
  from { transform: translateY(0); }
  to   { transform: translateY(-100px); }
}

/* Sticky header that fades in on scroll */
.site-header {
  animation: header-appear linear;
  animation-timeline: scroll(root);
  animation-range: 0px 200px; /* within first 200px of scroll */
}
@keyframes header-appear {
  from { background: transparent; backdrop-filter: none; }
  to   { background: rgba(0,0,0,0.9); backdrop-filter: blur(10px); }
}

/* JS interop — read scroll progress */
