// 2. Middleware injects hints based on segment
// middleware.ts
export function middleware(req: NextRequest) {
  const segment = req.cookies.get('user-segment')?.value ?? 'new';

  // Predictions from ML model (pre-computed, served from KV)
  const hints = PREFETCH_MAP[segment] ?? [];

  const res = NextResponse.next();
  if (hints.length) {
    res.headers.set('Link',
      hints.map(url => `<${url}>; rel=prefetch; as=script`).join(', ')
    );
  }
  return res;
}

// 3. Or inject speculation rules at edge
